"""Medium-scale fuzz: more tasks/groups/transactions on small topologies."""
import json, random, sys
sys.path.insert(0, '/workspace/tmp')
import ref, harness, fuzz

TOPOS = [
    lambda rng: ["clos", rng.choice([4, 6]), rng.choice(['tor', 'pod']), rng.choice([0, 1])],
    lambda rng: ["leaf-spine", rng.randint(2, 8), rng.randint(1, 4)],
    lambda rng: ["torus2d", rng.randint(3, 6), rng.choice(['host', 'row'])],
    lambda rng: ["torus3d", 3, rng.choice(['host', 'line'])],
    lambda rng: ["dragonfly", rng.choice([3, 5, 7, 9]), 2, 1, rng.choice(['router', 'group', 'target'])],
    lambda rng: ["dragonfly-plus", rng.choice([2, 3, 4]), rng.choice([1, 2, 3]), rng.choice([1, 2]),
                 1, rng.choice([0, 1]), rng.choice(['tor', 'group'])],
]

def build_session(rng):
    topology = rng.choice(TOPOS)(rng)
    try:
        N, templates, domains = ref.build_topology(topology)
    except Exception:
        return None
    if not templates:
        return None
    by_dom = {}
    for i, d in enumerate(domains):
        by_dom.setdefault(d, []).append(i)
    doms = sorted(by_dom)
    G = rng.randint(1, 60)
    D = rng.randint(1, 400)
    tasks = []
    for gid in range(G):
        if rng.random() < 0.15:
            continue
        cls = rng.choice([0, 1, 2, 10 ** 9])
        d = rng.choice(doms)
        for _ in range(rng.randint(1, max(1, D // max(1, G)))):
            tasks.append([rng.choice(by_dom[d]), gid, rng.choice([1, 3, 10 ** 9, 42]),
                          cls, 1 if rng.random() < 0.3 else 0])
    tasks = tasks[:D]
    if not tasks:
        return None
    D = len(tasks)
    loads = [0] * G
    for t in tasks:
        loads[t[1]] += t[2]
    groups = []
    for gid in range(G):
        if loads[gid] == 0:
            groups.append([rng.randint(0, 4), rng.randint(1, 10 ** 12)])
        else:
            budget = rng.choice([1, 2, 7, 10 ** 12])
            need = -(-loads[gid] // budget)
            while need > 64:
                budget = max(budget * 2, -(-loads[gid] // 64))
                need = -(-loads[gid] // budget)
            quota = min(64, max(1, need + rng.randint(0, 2)))
            if -(-loads[gid] // budget) > quota:
                budget = max(1, -(-loads[gid] // quota))
            groups.append([quota, budget])
    use = [0] * N
    member = [[] for _ in range(G)]
    for t in tasks:
        member[t[1]].append(t)
    for gid in range(G):
        if not member[gid]:
            continue
        fp = set()
        for t in member[gid]:
            fp.update(templates[t[0]])
        for node in fp:
            use[node] += groups[gid][0]
    caps = [use[i] + rng.randint(0, 2) for i in range(N)]
    sess = {"topology": topology, "caps": caps, "groups": groups, "tasks": tasks,
            "query": fuzz.make_query(rng, G, N, D), "transactions": []}
    txs = []
    for _ in range(rng.randint(1, 40)):
        edits = []
        for _ in range(rng.randint(0, 8)):
            kind = rng.randrange(8)
            if kind == 0:
                edits.append(["move", rng.randrange(D), rng.randrange(G)])
            elif kind == 1:
                edits.append(["weight", rng.randrange(D), rng.choice([1, 5, 10 ** 9])])
            elif kind == 2:
                edits.append(["class", rng.randrange(D), rng.choice([0, 1, 2, 10 ** 9])])
            elif kind == 3:
                edits.append(["bind", rng.randrange(D), rng.randrange(len(templates))])
            elif kind == 4:
                edits.append(["pin", rng.randrange(D), rng.choice([0, 1])])
            elif kind == 5:
                edits.append(["quota", rng.randrange(G), rng.randint(0, 10)])
            elif kind == 6:
                edits.append(["budget", rng.randrange(G), rng.randint(1, 10 ** 12)])
            else:
                edits.append(["cap", rng.randrange(N), rng.randint(0, max(1, max(caps) + 2))])
        txs.append({"revision": "@", "edits": edits, "query": fuzz.make_query(rng, G, N, D)})
    return sess, txs


def run_case(seed):
    rng = random.Random(seed)
    built = build_session(rng)
    if built is None:
        return None
    sess, txs = built
    s = ref.Session(dict(sess))
    if not s.legal():
        return None
    for tx in txs:
        if tx['revision'] == '@':
            tx['revision'] = s.revision
        else:
            tx['revision'] = s.revision + rng.randint(1, 3)
        s.transact(dict(tx))
    sess['transactions'] = [{k: tx[k] for k in ('revision', 'edits', 'query')} for tx in txs]
    request = {"version": 2, "sessions": [sess]}
    expected = ref.run(request)
    p = harness.run_request(request)
    if p.returncode != 0:
        return f'seed {seed}: rc={p.returncode} {p.stderr.decode()[:300]}'
    try:
        got = harness.strict_load(p.stdout)
    except Exception as e:
        return f'seed {seed}: bad json {e} {p.stdout[:200]}'
    if not harness.same(got, expected):
        return (f'seed {seed}: MISMATCH\n req={json.dumps(request)[:1500]}\n'
                f' got={json.dumps(got, default=str)[:1200]}\n exp={json.dumps(expected, default=str)[:1200]}')
    return None


if __name__ == '__main__':
    start = int(sys.argv[1]); count = int(sys.argv[2])
    bad = 0
    for seed in range(start, start + count):
        msg = run_case(seed)
        if msg:
            print(msg); bad += 1
            if bad > 2: break
    print('done', count, 'failures', bad)
